#define DT_DRV_COMPAT zephyr_i2c_emul_forwarding

#include <zephyr/device.h>
#include <zephyr/drivers/emul.h>
#include <zephyr/drivers/i2c.h>
#include <zephyr/drivers/i2c_emul.h>

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(i2c_emul_forwarding, CONFIG_I2C_LOG_LEVEL);

struct i2c_emul_forwarding_cfg {
	const struct device *fwd_bus;
	const struct emul *target;
	uint8_t *buf;
	uint32_t buf_size;
};

struct i2c_emul_forwarding_data {
	const struct device *dev;
	uint8_t *buf;
	uint32_t buf_len;
	uint32_t buf_ptr;
	bool buffering;
};

static int i2c_emul_forwarding_transfer(const struct emul *target, struct i2c_msg *msgs,
					    int num_msgs, int addr)
{
	const struct i2c_emul_forwarding_cfg *cfg = target->cfg;
	struct i2c_emul_forwarding_data *data = target->data;
	int ret = 0;

	if (cfg->fwd_bus) {
		struct i2c_msg fwd_msgs[num_msgs];

		memcpy(fwd_msgs, msgs, num_msgs * sizeof(struct i2c_msg));

		ret = i2c_transfer(cfg->fwd_bus, fwd_msgs, num_msgs, addr);

		if (ret == -EIO) {
			/*
			 * The underlying controller detected a read overflow (target
			 * provided more bytes than requested). The test framework
			 * expects this to be reported as -ENOMEM.
			 */
			return -ENOMEM;
		}

		return ret;
	}

	if (!data->buffering) {
		if (cfg->target == NULL) {
			return -EIO;
		}
		return cfg->target->api->transfer(cfg->target, msgs, num_msgs, addr);
	}

	for (int i = 0; i < num_msgs; i++) {
		if ((msgs[i].flags & I2C_MSG_RW_MASK) == I2C_MSG_READ) {
			if (data->buf_ptr + msgs[i].len > data->buf_len) {
				/* Not enough data in buffer */
				return -EIO;
			}
			memcpy(msgs[i].buf, &data->buf[data->buf_ptr], msgs[i].len);
			data->buf_ptr += msgs[i].len;
		} else {
			/* This is a write, so reset buffer and store new data */
			if (msgs[i].len > cfg->buf_size) {
				return -ENOMEM;
			}
			memcpy(data->buf, msgs[i].buf, msgs[i].len);
			data->buf_len = msgs[i].len;
			data->buf_ptr = 0;
		}
	}

	return 0;
}

static int i2c_emul_forwarding_read_req(const struct emul *target, uint8_t *val)
{
	struct i2c_emul_forwarding_data *data = target->data;
	const struct i2c_emul_forwarding_cfg *cfg = target->cfg;

	if (data->buffering) {
		if (data->buf_ptr >= data->buf_len) {
			return -EIO;
		}
		*val = data->buf[data->buf_ptr];
		data->buf_ptr++;

		return 0;
	}

	if (cfg->target == NULL) {
		return -EIO;
	}

	return cfg->target->api->read_requested(cfg->target, val);
}

static int i2c_emul_forwarding_write_req(const struct emul *target, uint8_t val)
{
	struct i2c_emul_forwarding_data *data = target->data;
	const struct i2c_emul_forwarding_cfg *cfg = target->cfg;

	if (data->buffering) {
		if (data->buf_len >= cfg->buf_size) {
			return -ENOMEM;
		}
		data->buf[data->buf_len] = val;
		data->buf_len++;

		return 0;
	}

	if (cfg->target == NULL) {
		return -EIO;
	}

	return cfg->target->api->write_received(cfg->target, val);
}

static int i2c_emul_forwarding_init(const struct emul *target)
{
	const struct i2c_emul_forwarding_cfg *cfg = target->cfg;
	struct i2c_emul_forwarding_data *data = target->data;

	data->dev = target->dev;
	data->buf = cfg->buf;
	data->buffering = data->buf != NULL;

	return 0;
}

static const struct i2c_emul_api i2c_emul_forwarding_api = {
	.transfer = i2c_emul_forwarding_transfer,
	.read_requested = i2c_emul_forwarding_read_req,
	.write_received = i2c_emul_forwarding_write_req,
};

#define I2C_EMUL_FORWARDING_BUF_ARRAY(inst)                                                        \
	static uint8_t i2c_emul_forwarding_buf_##inst[DT_INST_PROP(inst, buffer_size)];

#define I2C_EMUL_FORWARDING_BUF_PTR(inst) (i2c_emul_forwarding_buf_##inst)

#define I2C_EMUL_FORWARDING_BUF_DEFINE(inst)                                                       \
	COND_CODE_1(DT_INST_PROP_HAS_IDX(inst, buffer_size, 0),                                    \
		    (I2C_EMUL_FORWARDING_BUF_ARRAY(inst)), ())

#define I2C_EMUL_FORWARDING_BUF(inst)                                                              \
	COND_CODE_1(DT_INST_PROP_HAS_IDX(inst, buffer_size, 0),                                    \
		    (.buf = I2C_EMUL_FORWARDING_BUF_PTR(inst),                                      \
		     .buf_size = DT_INST_PROP(inst, buffer_size),),                                 \
		    (.buf = NULL, .buf_size = 0,))

#define I2C_EMUL_FORWARDING_DEVICE(inst)                                                           \
	I2C_EMUL_FORWARDING_BUF_DEFINE(inst);                                                      \
	static struct i2c_emul_forwarding_data i2c_emul_forwarding_data_##inst;                   \
	static const struct i2c_emul_forwarding_cfg i2c_emul_forwarding_cfg_##inst = {            \
		.fwd_bus = DEVICE_DT_GET_OR_NULL(DT_INST_PHANDLE(inst, forwarded_bus)),             \
		.target = EMUL_DT_GET_OR_NULL(DT_INST_PHANDLE(inst, forwarded_target)),            \
		I2C_EMUL_FORWARDING_BUF(inst)};                                                    \
	EMUL_DT_INST_DEFINE(inst, i2c_emul_forwarding_init, &i2c_emul_forwarding_data_##inst,     \
			  &i2c_emul_forwarding_cfg_##inst, &i2c_emul_forwarding_api, NULL)

DT_INST_FOREACH_STATUS_OKAY(I2C_EMUL_FORWARDING_DEVICE)
